package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAsianArtBank3 {
    private const val T = "පෙරදිග ආසියාතික කලාව (ඉන්දියාව, චීනය, ජපානය)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ මොහෙන්ජොදාරෝවෙන් හමු වූ 'පූජක රජුගේ' (Priest-King) ප්‍රතිමාව නෙළා ඇති ද්‍රව්‍යය කුමක්ද?", "සබන් ගල් හෙවත් ස්ටියටයිට් පාෂාණය", "තද කළුගල් හෙවත් ග්‍රැනයිට් පාෂාණය", "රන් ආලේපිත ලෝකඩ වාත්තුව", "වේලූ කොස් ලී හා හුණු බදාමය", "ත්‍රිපත්‍ර මෝස්තරයක් සහිත සළුවක් පොරවා සිටින කුඩා ස්ටියටයිට් ප්‍රතිමාව ඉන්දු කලාවේ සුවිශේෂී කෘතියකි."),
        q("මොහෙන්ජොදාරෝවෙන් හමු වූ කුඩා 'නටන යුවතිය' (Dancing Girl) ප්‍රතිමාව නිමවා ඇත්තේ කුමන මාධ්‍යයෙන් හා ක්‍රමයෙන්ද?", "මධූච්ඡිෂ්ට ක්‍රමයෙන් වාත්තු කළ ලෝකඩයෙනි", "රතු වැලිගල් කුට්ටියක කැටයම් කිරීමෙනි", "පිළිස්සූ ටෙරාකොටා මැටි ඇඹීමෙනි", "සබන් ගලින් අර්ධ උන්නතව නෙළීමෙනි", "වළලු පිරි වම් අත ඉණ මත තබා සිටින ඉරියව්ව ඉන්දු නිම්න ලෝහ වාත්තු කුසලතාව පෙන්වයි."),
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ මුද්‍රා (Seals) මත බහුලව කොටා ඇති සත්ව රූප හා ලක්ෂණ අතර කැපී පෙනෙන්නේ කුමක්ද?", "ඒකශෘංගී ගවයා, කුදු ගවයා හා පශුපති රුව", "මකර තොරණ, හංස පූට්ටුව හා භේරුණ්ඩ රුව", "සාරානාත් සිංහයන් සතර හා ධර්ම චක්‍රය", "ශිව නටරාජ හා ගජලක්ෂ්මී රූප සටහන", "කුඩා සබන් ගල් මුද්‍රාවල ඉහළින් කියවා නැති ඉන්දු අක්ෂර හා සත්ව රූප සියුම්ව කොටා ඇත."),
        q("ඉන්දියාවේ මෞර්ය යුගයේ 'ලෝමාස් රිෂි' (Lomas Rishi) ලෙන් විහාර ප්‍රවේශය ප්‍රසිද්ධ වන්නේ කුමන වාස්තු කැටයම නිසාද?", "ලී ආරුක්කු අනුකරණය කළ චෛත්‍ය කවුළුව", "මහල් දහයකින් යුත් ගඩොල් ගෝපුරය", "ග්‍රීක අයනික කැරලි සහිත ගල් කුළුණු", "චීන පැගෝඩා හැඩැති වහල කැටයම", "ගල තුළ කළ පැරණිතම බරාබර් ලෙනේ ඇතුළු වීමේ දොරටුව දැවමය චෛත්‍ය ආරුක්කුව සිහිගන්වයි."),
        q("අශෝක අධිරාජ්‍යයාගේ කුළුණු හිස් අතර 'රාම්පූර්වා වෘෂභ කුළුණු හිස' (Rampurwa Bull) අගය කරන්නේ කුමක් නිසාද?", "මෞර්ය ඔප දැමීම හා ස්වාභාවික මාංශ පේශි නෙළීම", "පියාපත් ඇති විකෘති කල්පිත රූප නිසා", "බිත්ති මත තෙල් සායමින් ඇඳ ඇති නිසා", "කඩදාසි පල්ප මාධ්‍යයෙන් තැනූ නිසා", "සාරානාත් සිංහ හිස මෙන්ම රාම්පූර්වා කුළු ගව රුව මෞර්ය යුගයේ යථාර්ථවාදී ශිලා මූර්ති ශිල්පය පෙන්වයි."),
        q("සාරානාත් අශෝක ස්තම්භ හිසේ පාදමේ (Abacus) ඇති ධර්ම චක්‍ර හතර අතර කැටයම් කර ඇති සතුන් හතර දෙනා කවුද?", "සිංහයා, ගවයා, අශ්වයා සහ ඇතා", "මොනරා, හංසයා, මකරා සහ නාගයා", "ව්‍යාඝ්‍රයා, මුවා, කිඹුලා සහ වඳුරා", "අශ්වයා, ඔටුවා, කොටියා සහ බැටළුවා", "මෙම සතුන් හතර දෙනාම අපගේ අනුරාධපුර සඳකඩපහණේද සංසාරික සංකේත ලෙස පසුකාලීනව යොදා ගැණිනි."),
        q("සාංචි මහා ස්තූපයේ නැගෙනහිර තොරණ කෙළවර එල්ලී සිටින වෘක්ෂ දේවතා මූර්ති හඳුන්වන්නේ කුමන නමින්ද?", "ශාලභංජිකා හෙවත් යක්ෂණී රූප", "ගන්ධාර බෝධිසත්ව රූප", "චෝල පාර්වතී ලෝකඩ රූප", "අජන්තා අප්සරා බිතුසිතුවම්", "අඹ ගසක අත්තක් අල්ලාගෙන ත්‍රිභංග ඉරියව්වෙන් සිටින ශාලභංජිකා රූප සශ්‍රීකත්වය සංකේතවත් කරයි."),
        q("ශුංග හා සාතවාහන යුගයේ සාංචි තොරණ හා භාරුත් කැටයම්වල බුදුන් වහන්සේ නිරූපණය කිරීමට යොදාගත් සංකේත මොනවාද?", "බෝධි වෘක්ෂය, සිරිපතුල්, ස්තූපය හා ධර්ම චක්‍රය", "උස් ශෛලමය හිටි හා හිඳි බුදු පිළිම", "වීණාව වයන ශිව දෙවි හා නටරාජ රුව", "කුරුස ලකුණ හා රන් පිහාටු ඔටුන්න", "බුදු පිළිම නෙළීම ඇරඹීමට පෙර අනිකොනික් (Aniconic) යුගයේදී සංකේත මගින් බුදුන් වැඳුම් ලැබීය."),
        q("මථුරා කලා සම්ප්‍රදායේ බුදු පිළිමවල දක්නට ලැබෙන විශේෂිත පාෂාණ වර්ගය හා ස්වරූපය කුමක්ද?", "සුදු තිත් සහිත රතු වැලිගල් හා පුළුල් උරහිස්", "තද අළු පැහැති ශිස්ට් ගල් හා ග්‍රීක රැලි", "කොළ පැහැති පල්නාඩ් හුණුගල් හා සිහින් බඳ", "රන් ආලේපිත තඹ හා පිළිස්සූ මැටි", "දේශීය යක්ෂ ප්‍රතිමා ආකෘතිය මත පදනම්ව රතු සික්රි වැලිගලින් බලසම්පන්න බුදු පිළිම නෙළීය."),
        q("ගන්ධාර කලා සම්ප්‍රදායේ බුදු පිළිම හඳුනා ගැනීමේදී චීවරය සහ හිසකෙස් නිරූපණය කර ඇත්තේ කෙසේද?", "ඝන රැලි සහිත සිවුර හා රැලි ගැසුණු කෙස්", "ඉතා තුනී ඇඟට ඇලුණු සිවුර හා මුඩු හිස", "විශාල ගිනිසිළු සිරස්පත හා පළල් උරහිස්", "රන් ඔටුන්න හා කැටයම් කළ මාල පළඳනා", "වයඹදිග ඉන්දියාවේ කුෂාණ යුගයේදී ග්‍රීක-රෝම හෙලනිස්තික කලා ආභාසය ගන්ධාරයට එක් විය."),
        q("අමරාවතී මූර්ති කලා සම්ප්‍රදාය ප්‍රධාන වශයෙන් භාවිත කළ මාධ්‍යය හා ශෛලීය ගුණය කුමක්ද?", "ලා කොළ හුණුගල් හා සජීවී ජන සමූහ කැටයම්", "තද කළුගල් හා හුදෙකලා සරල රූප", "ගඩොල් හා බදාම සිතුවම් මූර්ති", "දැව කැටයම් හා වර්ණවත් ලාක්ෂා", "ක්‍රිෂ්ණා ගංගා නිම්නයේ අමරාවතී හා නාගර්ජුනකොණ්ඩ කැටයම් ලංකාවේ මුල් අනුරාධපුර කලාවට බලපෑවේය."),
        q("ඉන්දීය කලාවේ 'ස්වර්ණමය යුගය' ලෙස සැලකෙන ගුප්ත යුගයේ (ක්‍රි.ව. 4–6) විශිෂ්ටතම කෘතියක් වන 'සාරානාත් හිඳි බුදු පිළිමයේ' මුද්‍රාව කුමක්ද?", "ධර්මචක්‍ර ප්‍රවර්තන මුද්‍රාව", "භූමිස්පර්ශ හෙවත් මාර විජය මුද්‍රාව", "අභය හෙවත් ආශීර්වාද මුද්‍රාව", "වරද හෙවත් දාන මුද්‍රාව", "බිම වැසූ දෙනෙත් හා පිටුපස කැටයම් කළ ප්‍රභාමණ්ඩලය සහිත මෙම පිළිමය ආධ්‍යාත්මික සංයමයේ කූටප්‍රාප්තියයි."),
        q("ගුප්ත යුගයේ සාරානාත් බුදු පිළිමයේ හිසට පිටුපසින් ඇති 'ප්‍රභාමණ්ඩලයේ' (Halo) විශේෂත්වය කුමක්ද?", "සියුම් ලියවැල් හා මල් මෝස්තර කැටයම් කිරීම", "කිසිදු කැටයමක් නොමැතිව හිස්ව තැබීම", "යුද රථ හා සිංහ රූප පෙළක් කැටයම් කිරීම", "ගිනි ගන්නා වළලු හතකින් වට කර තිබීම", "ගන්ධාරයේ හිස් ප්‍රභාමණ්ඩලය වෙනුවට ගුප්ත ශිල්පියා විසිතුරු ශාක ලියවැල් රටා කැටයම් කළේය."),
        q("අජන්තා ලෙන් විහාර සිතුවම් අතර ලෙන් අංක 1 හි දැකිය හැකි ඉතාම ලෝක ප්‍රසිද්ධ බෝධිසත්ව සිතුවම කුමක්ද?", "පද්මපාණි හා වජ්‍රපාණි බෝසත් සිතුවම්", "මාර පරාජය හා සිව්වනක් පිරිස", "විෂ්ණු හා ලක්ෂ්මී අනන්තශයන සිතුවම", "කණිෂ්ක රජුගේ යුද ජයග්‍රහණ සිතුවම", "නෙළුම් මලක් අතින් ගත් පද්මපාණිගේ කරුණාබර බැල්ම හා ත්‍රිභංග ලාලිත්‍යය අජන්තාවේ අග්‍ර ඵලයයි."),
        q("අජන්තා ලෙන් විහාර අංක 16 හි ඇඳ ඇති සංවේගජනක 'මිය යන කුමරිය' (Dying Princess) සිතුවමින් නිරූපණය වන චරිතය කවුරුන්ද?", "නන්ද කුමරුගේ බිරිඳ වූ සුන්දරී (ජනපද කල්‍යාණි)", "සිදුහත් කුමරුගේ මෑණියන් වූ මහාමායා දේවිය", "වෙස්සන්තර රජුගේ බිරිඳ වූ මද්‍රී දේවිය", "සීගිරි කාශ්‍යප රජුගේ දියණියකි", "නන්ද කුමරු පැවිදි වූ පුවත ඇසීමෙන් සිහිසුන් වන සුන්දරීගේ වේදනාව භාවාත්මකව සිතුවම් කර ඇත."),
        q("අජන්තා ලෙන් විහාරවල සිතුවම් ඇඳීම සඳහා පර්වත බිත්ති සකස් කළ මූලික බදාමය සෑදී ඇත්තේ කුමන ද්‍රව්‍යවලින්ද?", "මැටි, ගොම, වී පොතු හා හුණු බදාමයෙනි", "කෘත්‍රිම සිමෙන්ති, වැලි හා ජෙසෝවලිනි", "හණ තෙල් මිශ්‍ර කැන්වස් රෙදිවලිනි", "මී ඉටි හා තෙල් සායම් ස්තරවලිනි", "රළු ගල් මත මැටි හා කෙඳි තට්ටුවක් ගා ඊට උඩින් තුනී හුණු ස්තරයක් යොදා ටෙම්පරා ක්‍රමයට ඇන්දේය."),
        q("මහාරාෂ්ට්‍රයේ 'එල්ලෝරා කෛලාසනාථ දේවාලය' (ලෙන් අංක 16) ලෝක පුදුමයට පත් වන ප්‍රධාන වාස්තු තාක්ෂණය කුමක්ද?", "තනි කන්දක් මුදුනේ සිට පහළට හාරා නෙළීම", "පහළ සිට ඉහළට කළුගල් කුට්ටි බැඳ තැනීම", "දැව කුළුණු දහසක් මත ගොඩනැඟීම", "ගඩොල් හා මැටි බදාමයෙන් පුළුස්සා සෑදීම", "රාෂ්ට්‍රකූට පාලන සමයේදී බැසෝල්ට් පර්වතයක් කපා ඉවත් කරමින් මෙම දැවැන්ත ඒකශෛලීය දෙවොල නිමවීය."),
        q("තමිල්නාඩුවේ මහාබලිපුරම් (මාමල්ලපුරම්) හි පල්ලව යුගයේ කැටයම් අතර 'පංච රථ' හා 'ගංගා අවතරණය' කැටයම් කර ඇත්තේ කුමන මාධ්‍යයෙන්ද?", "තනි කළුගල් පර්වත කැටයම් මාධ්‍යයෙනි", "ලෝකඩ කුහර වාත්තු මාධ්‍යයෙනි", "වර්ණවත් ටෙරාකොටා මැටි පුවරුවලිනි", "ලී හා ඇත්දත් කැටයම් පුවරුවලිනි", "පල්ලව කලා සම්ප්‍රදායේ නාමල් කඳු ගැටවල නෙළූ ගංගා අවතරණය (අර්ජුනගේ තපස) දැවැන්ත අර්ධ උන්නත මූර්තියකි."),
        q("ඉන්දියාවේ ඔඩීෂා ප්‍රාන්තයේ පිහිටි 13 වන සියවසේ 'කොනාර්ක් සූර්ය දේවාලය' නිර්මාණය කර ඇත්තේ කුමන සුවිශේෂී හැඩයටද?", "කැටයම් කළ රෝද 24ක් හා අශ්වයන් 7ක රථයකි", "වෘත්තාකාර කළුගල් ස්තූපයක ආකාරයකි", "දිය අගලක් මැද ඇති පිරමීඩ කුළුණකි", "ලී පියස්සක් සහිත දිගු ශාලාවක ආකාරයකි", "කාලය හා පැය ගණන් මනින හිරු රථයක් ලෙස නිර්මාණය කර ඇති කොනාර්ක් දෙවොල කාලිංග නගර ශෛලියේ උච්චතම කෘතියකි."),
        q("උතුරු ඉන්දියානු හින්දු කෝවිල් (Nagara) සහ දකුණු ඉන්දියානු ද්‍රවිඩ කෝවිල් (Dravida) වෙන් කර හඳුනා ගන්නා ප්‍රධාන වහල අංගය කුමක්ද?", "වක්‍ර රේඛීය 'ශිඛරය' හා පිරමීඩමය 'විමානය'", "රෝමානු අර්ධ වෘත්තාකාර ගෝලාකාර ඩෝමය", "ගොතික් උල් ආරුක්කු හා පියාඹන ආධාරක", "ජපන් නැමුණු උළු වහල හා ටෝරි දොරටුව", "නගර ශෛලියේ වක්‍ර ශිඛරය මුදුනේ 'ආමලක' ඇති අතර ද්‍රවිඩ ශෛලියේ පියවරෙන් කුඩා වන විමානය හා ගෝපුර ඇත."),
        q("ඉන්දියාවේ තන්ජාවූර් හි 'බෘහදීශ්වර දේවාලය' (Brihadeeswarar Temple) ඉදි කරවන ලද්දේ කුමන රාජවංශය විසින්ද?", "චෝල රාජවංශය (රාජරාජ චෝල රජු)", "මෞර්ය රාජවංශය (අශෝක අධිරාජ්‍යයා)", "මෝගල් රාජවංශය (ෂා ජහාන් රජු)", "ගුප්ත රාජවංශය (චන්ද්‍රගුප්ත රජු)", "ක්‍රි.ව. 1010 දී නිමවූ මෙම ග්‍රැනයිට් දෙවොල දකුණු ඉන්දීය ද්‍රවිඩ ගෘහ නිර්මාණයේ දැවැන්තම නිදසුනකි."),
        q("ඉන්දියානු 'මෝගල් ක්ෂුද්‍ර සිතුවම්' (Mughal Miniature Paintings) කලාවේ ප්‍රධාන විෂය වස්තූන් හා ලක්ෂණ මොනවාද?", "රාජ සභා, දඩයම්, සත්ව රූප හා සියුම් රේඛා", "බෞද්ධ ජාතක කතා හා ගුහා සිතුවම් පමණි", "වියුක්ත ජ්‍යාමිතික කළු-සුදු ඉරි පමණි", "දැවැන්ත මීටර් දහයේ තෙල් සායම් කැන්වස්", "අක්බර් හා ජහන්ගීර් අධිරාජ්‍යයන් යටතේ පර්සියානු හා ඉන්දීය ශෛලි මුසුව ලේන ලොම් පින්සලින් කුඩා කෘති ඇන්දේය."),
        q("ජහන්ගීර් අධිරාජ්‍යයාගේ කාලයේ විසූ ප්‍රකට මෝගල් චිත්‍ර ශිල්පී 'උස්තාද් මන්සූර්' විශේෂයෙන් ප්‍රසිද්ධ වූයේ කුමන සිතුවම් සඳහාද?", "දුර්ලභ පක්ෂීන්, සතුන් හා මල්වල යථාර්ථවාදී රූප", "ග්‍රීක දෙවිවරුන්ගේ මූර්ති චිත්‍ර සඳහා", "වියුක්ත ජ්‍යාමිතික ලාංඡන නිර්මාණය සඳහා", "ජපන් සුමි-එ කඳුකර දිය ඇලි සඳහා", "මන්සූර් ඇඳි සයිබීරියානු කොකා සහ තුර්කි කුකුළා වැනි කුරුලු සිතුවම් විද්‍යාත්මකව පවා නිවැරදි වේ."),
        q("මෝගල් සිතුවම්වලට වඩා භක්ති රසය හා ප්‍රේමණීය කාව්‍ය ගුණය ඉස්මතු කළ 'රාජ්පුත් හා කංග්‍රා' (Rajput / Kangra) ක්ෂුද්‍ර සිතුවම්වල ප්‍රධාන තේමාව කුමක්ද?", "ක්‍රිෂ්ණා හා රාධාගේ රාසලීලා ආදර පුවත්", "රෝම අධිරාජ්‍යයේ යුද ජයග්‍රහණ පෙළ", "චීන අධිරාජ්‍යයේ පෝසිලේන් වෙළඳ ගමන්", "වැදි ජනතාවගේ ප්‍රාග් ඓතිහාසික දඩයම්", "මෝගල් රාජසභා විලාසිතාවන්ගෙන් වෙන්ව රාජස්ථාන් හා පහාරි කලාකරුවෝ දීප්තිමත් වර්ණයෙන් රාධා-ක්‍රිෂ්ණා ඇන්දෝය."),
        q("අග්‍රා නුවර පිහිටි 'ටජ් මහල්' ගොඩනැඟිල්ල ඉන්දු-ඉස්ලාමීය මෝගල් වාස්තු විද්‍යාවේ උච්චතම කෘතිය වන්නේ කුමන ද්‍රව්‍යය නිසාද?", "සුදු කිරිගරුඬ හා පියෙත්‍රා ඩුරා ගල් ඇල්ලීම", "රතු මැටි ගඩොල් හා දැව පේකඩ යෙදීම", "තනි කළුගල් කන්දක් කපා හැඩගැන්වීම", "වර්ණවත් පිඟන් මැටි හා ලාක්ෂා ආලේපය", "පූර්ණ සමමිතිය, ලූනු හැඩැති ගෝලාකාර ඩෝමය හා සතර මිනාර කුළුණු ටජ් මහලට අසමසම සුන්දරත්වයක් ගෙන දෙයි."),
        q("චීන කලාවේ ආරම්භක ලෝකඩ යුගය වන 'ෂැං රාජවංශ' (Shang Dynasty) සමයේ චාරිත්‍රානුකූල භාජනවල කැටයම් කළ බියකරු මුහුණු රටාව කුමක්ද?", "තාඕතියේ මුහුණු මෝස්තරය (Taotie Mask)", "මකර තොරණ හා කිබි මුහුණ මෝස්තරය", "ග්‍රීක මෙඩූසා සර්ප හිස් මෝස්තරය", "පලාපෙති හා බෝපත් ජ්‍යාමිතික රටාව", "සමමිතිකව බෙදුණු දෙපස ඇස් හා අං සහිත තාඕතියේ රටාව පුරාණ චීන ලෝකඩ වාත්තු කලාවේ සංකේතයකි."),
        q("චීනයේ පළමු අධිරාජ්‍යයා වූ 'චින් ෂි හුවාංගේ' සොහොන් ගැබෙන් හමු වූ 'ටෙරාකොටා හමුදාවේ' (Terracotta Army) කලාත්මක විශේෂත්වය කුමක්ද?", "සෑම භටයෙකුගේම මුහුණු හැඩය එකිනෙකට වෙනස් වීම", "සියලුම සොල්දාදුවන් එකම අච්චුවකින් වාත්තු කිරීම", "පිළිම සියල්ල කළුගලින් පමණක් නෙළා තිබීම", "පිළිමවල උස අඟල් හයකට වඩා කුඩා වීම", "ස්වභාවික මිනිස් ප්‍රමාණයෙන් පිළිස්සූ මැටි භටයන්, අශ්වයන් හා රථ 8000ක් පමණ මෙහි තැන්පත් කර තිබුණි."),
        q("චීන කලා ඉතිහාසයේ 'සේද මාවත' (Silk Road) හරහා බුදු දහම පැමිණීමත් සමඟ බිහි වූ දැවැන්ත ශෛලමය බුදු පිළිම කොහි දැකිය හැකිද?", "යුංගං, ලොංමෙන් සහ දුන්හුවාං ලෙන්වල", "මොහෙන්ජොදාරෝ සහ හරප්පා නටබුන්වල", "කියෝතෝ රියෝආන්-ජි ගල් උද්‍යානයේ", "මහාබලිපුරම් වෙරළබඩ දේවාල සංකීර්ණයේ", "ගන්ධාර හා මධ්‍ය ආසියානු ආභාසය චීන ශෛලියට හුරු වෙමින් දුන්හුවාං මොගාඕ ලෙන් සිතුවම් හා ලොංමෙන් මූර්ති බිහිවිය."),
        q("චීන චිත්‍ර හා අක්ෂර කලාවේදී ශිල්පියෙකු අනිවාර්යයෙන් භාවිත කරන 'අධ්‍යයනයේ නිධාන හතර' (Four Treasures) මොනවාද?", "පින්සල, තීන්ත කූර, තීන්ත ගල සහ කඩදාසි", "පැන්සල, මකනය, කෝදුව සහ පාට පෙට්ටිය", "මිටිය, නියන, වැලි කඩදාසි සහ ගල", "තෙල්, ටර්පන්ටයින්, කැන්වස් සහ පිහිය", "උණ බට පින්සල, සිහින් දැලි තීන්ත කූර, වතුර අඹරන ගල හා ෂුවාන් (Xuan) කඩදාසිය මෙයට අයත් වේ."),
        q("චීන චිත්‍ර ශිල්පී 'ෂියේ හේ' (Xie He) විසින් ඉදිරිපත් කළ චිත්‍ර කලාවේ මූලධර්ම හයෙන් පළමු හා වැදගත්ම රීතිය කුමක්ද?", "ජීව රිද්මය හා ප්‍රාණවත් ශක්තිය (Spirit Resonance)", "කෝදුවෙන් නිවැරදි රේඛීය දෘෂ්ටිකෝණය මැවීම", "තද ඇක්‍රිලික් වර්ණවලින් පසුබිම වැසීම", "ඡායාරූපයක් මෙන් සියුම්ව පිටපත් කිරීම", "හුදෙක් බාහිර හැඩය අනුකරණය කිරීමට වඩා චිත්‍රය තුළ අභ්‍යන්තර ජීව ශක්තිය රැඳීම චීන කලාවේ අරමුණයි."),
        q("සම්ප්‍රදායික චීන 'ෂාන්-ෂුයි' (Shan-Shui) භූ දර්ශන සිතුවම්වල ප්‍රධාන වශයෙන් අඳින ස්වාභාවික අංග දෙක මොනවාද?", "කඳු වැටි සහ ගලා යන ජල දහරා", "කාන්තාර වැලි කඳු සහ පිරමීඩ", "මුහුදු යුද නැව් සහ වරාය නගර", "විශාල නගර ගොඩනැගිලි සහ මංමාවත්", "කඳු යනු ස්ථිර යැං (Yang) ශක්තියද ජලය යනු මෘදු යින් (Yin) ශක්තියද නිරූපණය කරන තාඕවාදී දර්ශනය මෙහි වේ."),
        q("චීන සෝං (Song) රාජවංශ භූ දර්ශන සිතුවම්වල (උදා: ෆාන් කුවාන්, මා යුවාන්) 'හිස් අවකාශය' (Empty Space) තබන්නේ ඇයි?", "මීදුම, අනන්ත අවකාශය හා සිතීමට ඉඩ දීමට", "කඩදාසි මත තීන්ත අවසන් වූ බැවින්", "කුඩා අකුරු පසුව ලියා තැබීම සඳහා", "වර්ණ චක්‍රයේ උණුසුම අඩු කිරීම සඳහා", "බටහිර සිතුවම් මෙන් මුළු තලයම නොවසා හිස් අවකාශයද සංයුතියේ කොටසක් ලෙස භාවිත කිරීම ආසියාතික ගුණයකි."),
        q("චීන සම්ප්‍රදායික අත්සන් හා සිතුවම් මත තබන කුඩා 'රතු මුද්‍රාව' (Red Seal / Chop) කලා කෘතියට එක් කරන්නේ කුමක්ද?", "ශිල්පියාගේ අනන්‍යතාව හා වර්ණ උද්දීපනය", "කෘතියේ විකුණුම් මිල හා බදු මුදල", "රජයේ තහනම් නියෝගය හා අවවාදය", "සිතුවම කපා ඉවත් කළ යුතු සීමාව", "කළු-සුදු තීන්ත සිතුවමක සමබරතාව රකිමින් කලාකරුවාගේ හෝ එකතුකරන්නාගේ මුද්‍රාව රතු පැහැයෙන් තබයි."),
        q("චීන 'හෑන් රාජවංශ' (Han Dynasty) සමයේ මාවංඩුයි (Mawangdui) සොහොන් ගැබෙන් හමු වූ 'ටී-හැඩැති සේද ධජය' කුමක් සඳහා භාවිත වූවක්ද?", "මළගිය ආත්මය ස්වර්ගයට මඟ පෙන්වන සිතුවමකි", "වෙළඳසැලක ආහාර මිල ගණන් දැන්වූ පුවරුවකි", "බෞද්ධ විහාරයක දාන ශාලාවේ වැස්මකි", "රජුගේ විවාහ මංගල්‍ය උත්සව සැරසිල්ලකි", "සේද රෙද්ද මත පාතාලය, පෘථිවිය හා ස්වර්ගය යන ලෝක තුන සිතුවම් කර තිබීම පැරණි චීන විශ්වාස පෙන්වයි."),
        q("චීනයේ 'ටැං රාජවංශ' (Tang Dynasty) කාලයේ ඉතා ජනප්‍රිය වූ 'සන්කායි' (Sancai) පිඟන් මැටි කලාවේ ප්‍රධාන වර්ණ තුන මොනවාද?", "කහ-දුඹුරු, කොළ සහ ක්‍රීම් සුදු", "තද නිල්, රෝස සහ දම් පැහැය", "තනි කළු, අළු සහ රිදී පැහැය", "රතු, තැඹිලි සහ රන්වන් පැහැය", "සේද මාවතේ වෙළඳ ඔටුවන් හා අශ්වයන් මෙම වර්ණ තුනේ ග්ලේස් ආලේපයෙන් අලංකාරව නිමවීය."),
        q("චීනයේ 'මිං රාජවංශ' (Ming Dynasty) කාලයේ ලෝක ප්‍රසිද්ධ නිල්-සුදු පෝසිලේන් (Blue-and-White Porcelain) සඳහා ගත් නිල් වර්ණකය කුමක්ද?", "කොබෝල්ට් ඔක්සයිඩ් (Cobalt Oxide)", "ලැපිස් ලැසුලි රන් කුඩු (Ultramarine)", "කහ හිරියල් හා කොළ තඹ කුඩු", "කෘත්‍රිම ඇක්‍රිලික් නිල් තීන්ත", "සුදු කැඔලින් මැටි බඳුන් මත කොබෝල්ට් නිල් රටා ඇඳ විනිවිද පෙනෙන ග්ලේස් දමා අධික උෂ්ණත්වයේ පිළිස්සීය."),
        q("සම්ප්‍රදායික චීන පැගෝඩා (Pagoda) ගොඩනැඟිල්ල කුමන ඉන්දියානු බෞද්ධ වාස්තු අංගයෙන් පරිණාමය වූවක්ද?", "ඉන්දියානු ස්තූපයේ ඡත්‍රාවලියෙන් හා මහල් කුළුණෙන්", "ග්‍රීක පාතනන් දෙවොලේ ත්‍රිකෝණ පෙදිමෙන්තුවෙන්", "රෝමානු කොලෝසියම් ආරුක්කු පෙළෙන්", "මිසරයේ ස්ෆින්ක්ස් මූර්ති ආකෘතියෙන්", "ඉන්දියානු ස්තූපයේ කොත් කැරැල්ල චීන දැවමය බහු-මහල් නැරඹුම් කුළුණු සමඟ මුසු වී පැගෝඩාව බිහිවිය."),
        q("චීන කලාවේ 'චාරුලේඛන' (Chinese Calligraphy) හුදෙක් අකුරු ලිවීමකට වඩා ඉහළ කලා අංගයක් ලෙස සලකන්නේ ඇයි?", "පින්සල් පහරින් කලාකරුගේ චරිතය හා රිද්මය පෙනේ", "එය ඉතා වේගයෙන් රහස් පණිවිඩ ලියන බැවින්", "කළු තීන්ත මිල අධික වටිනා ද්‍රව්‍යයක් නිසා", "කෝදුවෙන් මැන සමාන කොටු තුළ ලියන නිසා", "චිත්‍ර ඇඳීමේ පින්සල් ශිල්පය හා අක්ෂර ලිවීම එකම මූලධර්ම මත රඳා පවතින බව චීන ශිල්පීහු විශ්වාස කරති."),
        q("චීනයේ තාඕවාදී දර්ශනය යටතේ බිහි වූ සම්ප්‍රදායික 'චීන උද්‍යාන කලාවේ' (Chinese Garden) ප්‍රධාන අංග මොනවාද?", "විකෘති හැඩැති ගල්, ජලය, පැළ හා මණ්ඩප", "සමමිතික කෙළින් කපන ලද පඳුරු පේළි", "විශාල ප්ලාස්ටික් ප්‍රතිමා හා නියොන් විදුලි පහන්", "කොන්ක්‍රීට් තාර මාවත් හා ග්‍රීක කුළුණු", "සොබාදහමේ අසමමිතික රිද්මය අනුකරණය කරමින් සෑම හැරවුමකදීම නව දසුනක් මැවෙන සේ උද්‍යාන සකසයි."),
        q("ජපානයේ ප්‍රාග් ඓතිහාසික 'ජෝමොන්' (Jomon) යුගයේ මැටි බඳුන් හඳුන්වන 'ජෝමොන්' යන වචනයේ අරුත කුමක්ද?", "ලණු සලකුණු රටා (Cord-Marked)", "රන් ආලේපිත ග්ලේස් (Gold Glazed)", "සෙල්මුවා කැටයම් (Stone Carved)", "මුහුදු බෙල්ලන් (Sea Shells)", "ලෝකයේ පැරණිතම මැටි බඳුන් අතරට ගැනෙන ජෝමොන් බඳුන් මතුපිට තෙත් මැටියේ ලණු එබීමෙන් සැරසීය."),
        q("ජපානයේ කෝෆුන් (Kofun) යුගයේ සොහොන් ගොඩැලි වටා තැන්පත් කළ පිළිස්සූ මැටි රූප හඳුන්වන්නේ කුමන නමින්ද?", "හනිවා මැටි රූප (Haniwa)", "නෙට්සුකේ ඇත්දත් රූප (Netsuke)", "ෂිකිෂි කඩදාසි පත්‍ර (Shikishi)", "ඩරුමා බෝනික්කන් (Daruma)", "මිනිස්, සත්ව, ගෙවල් හා ආයුධ හැඩයෙන් කුහර මැටි සිලින්ඩර ලෙස තැනූ හනිවා රූප ඉතා සරල හා ආකර්ෂණීය වේ."),
        q("ජපානයේ ෂින්ටෝ පූජනීය ස්ථානවල පිවිසුම් දොරටුව සංකේතවත් කරන සාම්ප්‍රදායික රතු දැවමය ද්වාරය කුමක්ද?", "ටෝරි ද්වාරය (Torii Gate)", "සාංචි තොරණ (Sanchi Torana)", "වටදාගෙය (Vatadage)", "ගෝපුරම (Gopuram)", "තිරස් හා සිරස් කණු දෙක බැගින් සෑදෙන ටෝරි දොරටුව ලෞකික ලෝකයෙන් ආධ්‍යාත්මික බිමට පිවිසීම පෙන්වයි."),
        q("ලෝකයේ පැරණිතම දැනට පවතින දැවමය ගොඩනැඟිල්ල ලෙස සැලකෙන ජපානයේ අසුකා යුගයේ බෞද්ධ විහාරය කුමක්ද?", "නාරා හි හොරියු-ජි විහාරය (Horyu-ji)", "තෝකියෝ හි සෙන්සෝ-ජි විහාරය", "කියෝතෝ හි කින්කාකු-ජි මැදුර", "කමකුරා හි කෝතොකු-ඉන් පිළිමය", "හිනෝකි (Japanese Cypress) දැවයෙන් නිමවූ මහල් පහේ පැගෝඩාව හා කොන්ඩෝ ශාලාව හොරියු-ජි හි පිහිටා ඇත."),
        q("ජපානයේ හෙයියාන් (Heian) යුගයේදී 'චීන ශෛලියෙන්' වෙන්ව දේශීය ජපන් කතා හා ජීවිතය ඇඳි සිතුවම් කලාව කුමක්ද?", "යමතෝ-එ (Yamato-e) සිතුවම් කලාව", "මෝගල් ක්ෂුද්‍ර සිතුවම් කලාව", "අජන්තා ටෙම්පරා බිතුසිතුවම් කලාව", "රෙනේසාන්ස් තෙල් සායම් කලාව", "දිගු අත් පිටපත් ලියවිලි (Emakimono) තුළ 'ගෙන්ජි කතා පුවත' වැනි දේශීය කතා දීප්තිමත් වර්ණයෙන් ඇන්දේය."),
        q("ජපන් හෙයියාන් යුගයේ 'ගෙන්ජි කතා පුවත' වැනි අත් පිටපත් සිතුවම්වල 'වහලය ඉවත් කර ඇතුළත පෙන්වීමේ' ක්‍රමය කුමක්ද?", "ෆුකිනුකි යතායි (Fukinuki Yatai) ක්‍රමය", "චියරොස්කුරෝ (Chiaroscuro) ක්‍රමය", "ස්ෆුමාටෝ (Sfumato) මීදුම් ක්‍රමය", "කියුබිසම් (Cubism) බහු-කෝණ ක්‍රමය", "ඉහළ සිට විකර්ණ කෝණයකින් බලා වහලය නොමැතිව ගෘහ අභ්‍යන්තරයේ චරිත පෙන්වීම මෙම උපක්‍රමයයි."),
        q("කමකුරා යුගයේ 'තෝදයි-ජි' විහාර දොරටුවේ ප්‍රචණ්ඩ ආරක්ෂක දේවතා (Nio Guardians) දැව ප්‍රතිමා නෙළූ මූර්ති ශිල්පියා කවුද?", "උන්කෙයි (Unkei) හා කයිකෙයි", "හොකුසායි (Hokusai) හා හිරොෂිගේ", "සෙෂූ තොයෝ (Sesshu Toyo)", "මුරසාකි ෂිකිබු (Murasaki Shikibu)", "තීව්‍ර මාංශ පේශි හා ගලා යන සළු සහිත දැවමය කොන්ගෝ රිකිෂි රූප කමකුරා යුගයේ යථාර්ථවාදී ශක්තිය පෙන්වයි."),
        q("සෙන් බුදු දහමේ ආභාසයෙන් ජපානයේ මුරොමාචි යුගයේදී බිහි වූ 'කළු තීන්ත පමණක් යොදා අඳින' චිත්‍ර සම්ප්‍රදාය කුමක්ද?", "සුයිබොකුගා හෙවත් සුමි-එ (Sumi-e)", "උකියෝ-එ වර්ණ ලී මුද්‍රණය (Ukiyo-e)", "මංගා ඩිජිටල් චිත්‍ර කලාව (Manga)", "කින්ට්සුගි රන් මැටි අලුත්වැඩියාව", "සෙෂූ තොයෝ වැනි සෙන් භික්ෂු ශිල්පීන් අඩුම පින්සල් පහර ගණනකින් ගැඹුරු ආධ්‍යාත්මික දසුන් මැවූහ."),
        q("කියෝතෝ නගරයේ 'රියෝආන්-ජි' (Ryoan-ji) සෙන් විහාරයේ ඇති 'කරේ-සන්සුයි' (Kare-sansui) උද්‍යානය සැකසී ඇත්තේ කුමකින්ද?", "සුදු බොරළු වැලි රටා සහ පර්වත ගල් 15කින්", "වර්ණවත් රෝස මල් හා ජල මල් උල්පත්වලින්", "දැවැන්ත ලෝකඩ ප්‍රතිමා පනහකින්", "උණ බට පාලම් හා පැගෝඩා දහයකින්", "ජලය නොමැති වියළි ගල් උද්‍යානයේ සුදු වැලි පීරා ඇති රැලි සාගරයද ගල් දූපත්ද සංකේතවත් කරමින් භාවනාවට උදව් වේ."),
        q("ජපානයේ එදෝ යුගයේ (Edo Period) ජනප්‍රිය වූ 'උකියෝ-එ' (Ukiyo-e) කලාව යනු කුමක්ද?", "ලී කුට්ටි මගින් කළ බහු-වර්ණ මුද්‍රණ කලාව", "මැටි කෝප්ප මත රන් පෑස්සීමේ කලාව", "සත්ව ඇටකටු මත සිතුවම් ඇඳීමේ කලාව", "කළුගල් ගුහාවල බුදු පිළිම නෙළීමේ කලාව", "'පාවෙන ලෝකයේ සිතුවම්' යන අරුතැති උකියෝ-එ මුද්‍රණ කබුකි නළුවන්, රූමතියන් හා භූ දර්ශන පෙන්වීය."),
        q("කත්සුෂිකා හොකුසායි (Katsushika Hokusai) නිර්මාණය කළ 'කනගාවා හි මහා රළ' (Great Wave off Kanagawa) සිතුවම අයත් කෘති මාලාව කුමක්ද?", "ෆූජි කන්දේ දසුන් තිස්හය (36 Views of Mt. Fuji)", "තොකයිඩෝ මාවතේ නැවතුම් පනස්තුන", "කියෝතෝ පන්සල් සියයේ කතා පුවත", "ජපන් තේ උත්සවයේ රකු බඳුන් මාලාව", "ප්‍රෂියානු නිල් (Prussian Blue) වර්ණය යොදා මුද්‍රණය කළ මහා රළ හා ඈත ෆූජි කන්ද ලෝක කලා ඉතිහාසයේ සංකේතයකි."),
        q("උතගාවා හිරොෂිගේ (Utagawa Hiroshige) වඩාත් ප්‍රසිද්ධ වූ 'තොකයිඩෝ මාවතේ නැවතුම් 53' මුද්‍රණ මාලාවේ ප්‍රධාන තේමාව කුමක්ද?", "වැස්ස, හිම හා ඍතු වෙනස් වන ස්වභාව දර්ශන", "බිහිසුණු සමුරායි යුද කඳවුරු සටන්", "චීන පෝසිලේන් කර්මාන්තශාලා අභ්‍යන්තරය", "රෝමානු හා ග්‍රීක පුරාවෘත්ත කතා", "මිනිසා සහ පරිසරයේ වැසි-සීතල මනෝභාවයන් වර්ණ ක්‍රමානුකූල වෙනස්වීමෙන් (Bokashi) මැනවින් පෙන්වීය."),
        q("ජපානයේ සාම්ප්‍රදායික මැටි බඳුන් කලාවේ 'කින්ට්සුගි' (Kintsugi) යනු කුමක්ද?", "බිඳුණු මැටි බඳුන් රන් කුඩු මිශ්‍ර ලාක්ෂාවෙන් ඇලවීම", "අලුත් මැටි බඳුන් මුහුදු පතුලේ ගිල්වා තැබීම", "වීදුරු කැබලිවලින් බිත්ති සැරසීම", "කඩදාසි නවා පක්ෂි රූප තැනීම", "කැඩී බිඳී ගිය බව සැඟවීම වෙනුවට එම පැලුම් රන් රේඛාවලින් අගය කිරීමේ වාබි-සාබි දර්ශනය මෙහි වේ."),
        q("ජපන් කලා දර්ශනයේ 'වාබි-සාබි' (Wabi-Sabi) සංකල්පය මගින් අගය කරනු ලබන්නේ කුමන සුන්දරත්වයද?", "අසම්පූර්ණ බව, සරල බව හා අනිත්‍ය ස්වභාවය", "අධික දිලිසෙන රන් ආභරණ හා රාජකීය පෞඪත්වය", "පරිපූර්ණ ජ්‍යාමිතික සමමිතිය හා සුමට බව", "යාන්ත්‍රික සමාන බව හා විශාල කර්මාන්ත ශාලා", "තේ උත්සවයේ රකු (Raku) මැටි බඳුන් හා මල් සැකසුම්වල මෙම අව්‍යාජ සරල අසම්පූර්ණ බව සැමරේ."),
        q("කඩදාසි නොකපා හා මැලියම් නොගා තනි හතරැස් කඩදාසියක් නැමීමෙන් රූප තනන ජපන් කලාව කුමක්ද?", "ඔරිගාමි (Origami)", "ඉකෙබානා (Ikebana)", "බොන්සායි (Bonsai)", "නෙට්සුකේ (Netsuke)", "ජ්‍යාමිතික නැමුම් ශිල්පය ඔස්සේ කොකා (Crane) වැනි සතුන් හා නවීන නිර්මාණ බිහි කෙරේ."),
        q("සෘතු බේදය, හිස් අවකාශය හා සමබරතාව මුල් කරගත් සාම්ප්‍රදායික ජපන් 'මල් සැකසුම් කලාව' හඳුන්වන්නේ කුමන නමින්ද?", "ඉකෙබානා (Ikebana)", "ඔරිගාමි (Origami)", "හනිවා (Haniwa)", "සුමි-එ (Sumi-e)", "මල් පමණක් නොව කොළ, වියළි අතු හා බඳුන අතර ස්වර්ගය-පෘථිවිය-මිනිසා යන රේඛා සමබරතාව මෙහි අගය කෙරේ."),
        q("කිතගාවා උතමාරෝ (Utamaro) සහ තෝෂුසායි ෂරාකු (Sharaku) ජපන් උකියෝ-එ මුද්‍රණ කලාවේ විශේෂත්වයක් දැක්වූයේ කුමන රූප සඳහාද?", "රූමත් කාන්තා (Bijin-ga) හා කබුකි නළු ආලේඛ්‍ය", "මුහුදු රළ හා ගිනිකඳු භූ දර්ශන පමණක්", "කුඩා කෘමීන් හා ශාක මුල් සිතුවම්", "යුද ගුවන් යානා හා නාවික සටන්", "මුහුණේ හැඟීම් හා කිමෝනෝ වස්ත්‍ර රටා ඉතා තියුණු රේඛාවලින් ඔවුන් ලී කුට්ටි මුද්‍රණයට නැඟූහ."),
        q("ආසියානු කලා ඉතිහාසයේ ජපන් උකියෝ-එ ලී මුද්‍රණ 19 වන සියවසේදී කුමන බටහිර කලා ව්‍යාපාරයට ප්‍රබල ආභාසයක් ලබා දුන්නේද?", "ප්‍රංශ උපස්ථිතිවාදයට (Impressionism)", "ප්‍රාග් ඓතිහාසික ගුහා කලාවට", "පුරාණ මිසර පිරමීඩ කලාවට", "මධ්‍යකාලීන ගොතික් කැතීඩ්‍රල් කලාවට", "වැන් ගෝ, මොනේ හා ඩෙගා වැනි යුරෝපීය ශිල්පීන් ජපන් මුද්‍රණවල පැතලි වර්ණ හා අසමමිතික සංයුති අනුගමනය කළහ."),
        q("ඉන්දු-ශ්‍රී ලංකා කලා සම්බන්ධතා අනුව අනුරාධපුර සඳකඩපහණ හා බුදු පිළිම සඳහා ඍජුවම ආභාසය ලැබුණු දකුණු ඉන්දීය සම්ප්‍රදාය කුමක්ද?", "අමරාවතී සහ පල්ලව සම්ප්‍රදායන්", "ගන්ධාර සහ මෝගල් සම්ප්‍රදායන්", "චීන සෝං සහ මිං සම්ප්‍රදායන්", "ජපන් උකියෝ-එ සහ සෙන් සම්ප්‍රදායන්", "අනුරාධපුර මුල් පිළිමවලට අමරාවතී හා ගුප්ත ආභාසයත්, ඉසුරුමුණියට පල්ලව ආභාසයත් ලැබිණි."),
        q("ඉන්දියාවේ කාමුක මූර්ති කැටයම් හා උස් 'නගර ශිඛර' කුළුණු සඳහා ලෝක ප්‍රසිද්ධ මධ්‍ය ප්‍රදේශ් හි දේවාල සංකීර්ණය කුමක්ද?", "ඛජුරාහෝ දේවාල සංකීර්ණය (Khajuraho)", "සාංචි බෞද්ධ ස්තූප සංකීර්ණය", "මොහෙන්ජොදාරෝ නාන තටාක සංකීර්ණය", "හොරියු-ජි ලී විහාර සංකීර්ණය", "චන්දෙල්ලා රාජවංශය විසින් ඉදිකළ ඛජුරාහෝ දේවාල (කන්දාරිය මහාදේව) නගර වාස්තු කලාවේ මුදුන්මල්කඩකි."),
        q("ඉන්දියාවේ බිහාර් ප්‍රාන්තයේ පිහිටි, රේඛීය ගඩොල් කැටයම් හා භාරතීය වාස්තු කලාවේ උරුමයක් වන බුදුන් බුදු වූ ස්ථානයේ විහාරය කුමක්ද?", "බුද්ධගයා මහාබෝධි විහාරය", "බරාබර් ලෝමාස් රිෂි ගුහාව", "තන්ජාවූර් බෘහදීශ්වර දේවාලය", "අග්‍රා ටජ් මහල් මන්දිරය", "වජ්‍රාසනය හා අලංකාර ගල් වැට සහිත පිරමීඩාකාර ශිඛරයකින් යුත් මහාබෝධි විහාරය බෞද්ධ කලාවේ කේන්ද්‍රයයි."),
        q("ඉන්දියාවේ අග්‍රා නුවර 'ෆතේපූර් සික්රි' (Fatehpur Sikri) නගරය සහ 'හුමායුන්ගේ සොහොන් ගැබ' කුමන කලා යුගයේ කෘතිද?", "මෝගල් වාස්තු විද්‍යා යුගයේ", "ඉන්දු නිම්න ශිෂ්ටාචාර යුගයේ", "මෞර්ය අශෝක අධිරාජ්‍ය යුගයේ", "පල්ලව ශෛලමය ගුහා යුගයේ", "රතු වැලිගල් හා සුදු කිරිගරුඬ මිශ්‍ර කරමින් අක්බර් අධිරාජ්‍යයා මෝගල් වාස්තු ශෛලිය දියුණු කළේය."),
        q("චීන කලා ඉතිහාසයේ මුල් කාලීන 'වියුක්ත සංකේත' හා රන් ආලේපිත අලංකරණ සඳහා යොදාගත් වටිනාම හරිත හා සුදු පාෂාණය කුමක්ද?", "ජේඩ් පාෂාණය (Jade / කොළ මැණික් ගල)", "ග්‍රැනයිට් හෙවත් කළුගල් කුට්ටි", "හිරිගල් හෙවත් කැල්සයිට් පාෂාණය", "මෘදු ප්ලාස්ටර් ඔෆ් පැරිස් බදාමය", "නියෝලිතික ලියැංෂු යුගයේ (Bi discs, Cong tubes) සිට චීන සංස්කෘතියේ ජේඩ් පාරිශුද්ධත්වයේ සංකේතය විය."),
        q("සම්ප්‍රදායික ජපන් චිත්‍ර කලාවේ 'මොකොත්සු' (Mokkotsu - Boneless Method) ශිල්පය යනු කුමක්ද?", "බාහිර කළු සමෝච්ඡ රේඛා නොමැතිව වර්ණ පින්සල් පහරින් ඇඳීම", "මිනිස් අස්ථි ව්‍යුහය පමණක් පැන්සලෙන් ඇඳීම", "දැව කැබලි මත යකඩ ඇණ ගසා මුද්‍රණය කිරීම", "වීදුරු තහඩු මත තෙල් සායමින් රූප ඇඳීම", "පින්සලේ තීන්ත තානය මාරු කරමින් තනි පහරින් මල් පෙති හා උණ බට පත්‍ර මැවීමට මෙම ක්‍රමය යොදයි."),
        q("ඉන්දියාවේ මහාරාෂ්ට්‍ර ප්‍රාන්තයේ 'එලිෆැන්ටා ගුහාවල' (Elephanta Caves) හමුවන දැවැන්ත ශිලා මූර්තියෙන් දැක්වෙන්නේ කවුරුන්ද?", "හිස් තුනේ මහේෂ්මූර්ති ශිව (Trimurti Shiva)", "සිව් බුදුවරුන්ගේ සමාධි පිළිම", "විෂ්ණුගේ වරාහ අවතාර මූර්තිය", "ඉන්දු නිම්නයේ කුදු ගවයාගේ රුව", "මීටර් හයක් පමණ උස තනි පර්වතයේ නෙළූ ත්‍රිමූර්ති ශිව මූර්තිය ඉන්දීය පශ්චාත් ගුප්ත කලාවේ විශිෂ්ට කෘතියකි."),
        q("ඉන්දියාවේ ආන්ද්‍රා සහ කර්ණාටක ප්‍රදේශවල 'බාදාමි, අයිහොලේ හා පට්ටදකල්' හි දැකිය හැකි හින්දු කෝවිල් ගොඩනැඟුවේ කුමන රාජවංශයද?", "චාලුක්‍ය රාජවංශය (Chalukya Dynasty)", "මෞර්ය රාජවංශය (Maurya Dynasty)", "මින්ග් රාජවංශය (Ming Dynasty)", "හෙයියාන් රාජවංශය (Heian Period)", "නගර හා ද්‍රවිඩ ශෛලීන් දෙකම එකම තැනක අත්හදා බැලූ චාලුක්‍ය ශිල්පීන් ඉන්දීය වාස්තු කලාව පෝෂණය කළහ."),
        q("ඉන්දියාවේ 'නාලන්දා' සහ 'කුර්කිහාර්' වලින් හමු වූ පාල යුගයේ (Pala Dynasty) ලෝකඩ ප්‍රතිමා කුමන ආගමට අයත්ද?", "වජ්‍රයාන හා මහායාන බුදු දහමට", "ක්‍රිස්තියානි බැරොක් කලා සම්ප්‍රදායට", "ජපන් ෂින්ටෝ කාමි ඇදහිලිවලට", "මිසර ඔසිරිස් මරණ පූජා විධිවලට", "බෙංගාලයේ පාල යුගයේ තඹ හා ලෝකඩ බෝසත් ප්‍රතිමා ඉන්දුනීසියාව, ටිබෙට් හා ලංකාව කෙරෙහි බලපෑවේය."),
        q("ඉන්දියානු 'කාලිඝාට්' (Kalighat Painting) ජන සිතුවම් කලාව 19 වන සියවසේදී බිහි වූයේ කුමන නගරය ආශ්‍රිතවද?", "කල්කටාවේ කාලි දෙවොල අසල", "දිල්ලියේ රතු බලකොටුව අසල", "මදුරාසියේ මයිලාපූර් වෙරළේ", "මුම්බායිහි එලිෆැන්ටා දූපතේ", "මිල අඩු කඩදාසි මත වේගවත් පින්සල් පහරින් පත්‍ර සිතුවම් ඇඳ බැතිමතුන්ට විකිණීමෙන් නූතන ඉන්දීය කලාවටද මග පෑදිණි."),
        q("නූතන ඉන්දියානු කලා පුනරුදයේ පියා ලෙස සැලකෙන 'බෙංගාල කලා ගුරුකුලයේ' නිර්මාතෘවරයා කවුරුන්ද?", "අබනීන්ද්‍රනාත් තාගෝර් (Abanindranath Tagore)", "රවි වර්මා (Raja Ravi Varma)", "පැබ්ලෝ පිකාසෝ (Pablo Picasso)", "අමෘතා ෂේර්-ගිල් (Amrita Sher-Gil)", "බටහිර ඇකඩමික් ක්‍රමය ප්‍රතික්ෂේප කර අජන්තා, මෝගල් හා ජපන් ජල සායම් (Wash) ආභාසයෙන් දේශීය කලාවක් බිහි කළේය."),
        q("භාරතීය කලා කෘතිවලට බටහිර තෙල් සායම් යථාර්ථවාදය මුලින්ම මුසු කරමින් දේව රූප මුද්‍රණයෙන් ජනප්‍රිය කළ ඉන්දීය ශිල්පියා කවුද?", "රාජා රවි වර්මා (Raja Ravi Varma)", "උස්තාද් මන්සූර් (Ustad Mansur)", "සෙෂූ තොයෝ (Sesshu Toyo)", "ෆාන් කුවාන් (Fan Kuan)", "කේරළයේ උපන් රවි වර්මා රාමායණ හා මහාභාරත දර්ශන යුරෝපීය තෙල් සායම් ශිල්පයෙන් සිතුවම් කළේය."),
        q("චීනයේ සිචුවාන් ප්‍රාන්තයේ පිහිටි ලෝකයේ විශාලතම ශෛලමය 'ලෙෂාන් යෝධ බුදු පිළිමය' (Leshan Giant Buddha) නෙළා ඇත්තේ කුමන යුගයේද?", "ටැං රාජවංශ යුගයේදී (8 වන සියවස)", "ෂැං රාජවංශ යුගයේදී (ක්‍රි.පූ. 1500)", "චින් රාජවංශ යුගයේදී (ක්‍රි.පූ. 210)", "චිං රාජවංශ යුගයේදී (19 වන සියවස)", "ගංගා තුනක් හමුවන ගිරි දුර්ගයක මීටර් 71ක් උසට පර්වතයේ නෙළා ඇති මෛත්‍රේය බුදු පිළිමය විශිෂ්ටය."),
        q("ජපානයේ හෙයියාන් යුගයේ අවසාන කාලයේ 'වියෝදෝ-ඉන්' (Byodo-in Phoenix Hall) විහාරයේ ඇති රන්වන් අමිදා බුදු පිළිමය නිම කළ මූර්ති ශිල්පියා කවුද?", "ජෝචෝ (Jocho)", "උන්කෙයි (Unkei)", "හොකුසායි (Hokusai)", "ෂරාකු (Sharaku)", "ලී කුට්ටි කිහිපයක් එකට එකතු කර මූර්ති තැනීමේ 'යොසෙගි-සුකුරි' (Yosegi-zukuri) ක්‍රමය ජෝචෝ පරිපූර්ණ කළේය."),
        q("ජපානයේ සම්ප්‍රදායික 'නෝ රංග කලාව' (Noh Theatre) සඳහා දැවයෙන් නෙළන ලද වෙස්මුහුණුවල විශේෂ කලාත්මක ගුණය කුමක්ද?", "බලන කෝණය අනුව හැඟීම් වෙනස් වී පෙනීම", "රත්තරන් හා මැණික් කැට සියයක් ඇල්ලීම", "පිළිස්සූ මැටියෙන් මුහුණක් නැතිව තැනීම", "කඩදාසිවලින් පමණක් තාවකාලිකව කැපීම", "ආලෝකය වැටෙන ආකාරය හා නළුවා හිස ඇල කරන කෝණය අනුව එකම වෙස්මුහුණේ සිනහව හෝ දුක මතු වේ."),
        q("ආසියාතික කලාව තුළ ඉන්දීය, චීන හා ජපන් කලාවන්ට පොදු වූ ප්‍රධාන දාර්ශනික ලක්ෂණය කුමක්ද?", "සොබාදහම සමඟ ආධ්‍යාත්මික සමගිය හා සංකේතවාදය", "ත්‍රිමාණ ගණිතමය රේඛීය දෘෂ්ටිකෝණය පමණි", "රෝමානු අධිරාජ්‍යයේ යුද්ධෝපකරණ ප්‍රදර්ශනය", "තනි කාර්මික යන්ත්‍ර සූත්‍ර වර්ණනා කිරීම", "පෙරදිග කලාවේ මුඛ්‍ය අරමුණ බාහිර භෞතික පිටපත් කිරීමට වඩා අභ්‍යන්තර ජීව ශක්තිය හා ශාන්තිය පෙන්වීමයි."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ චිත්‍ර කලා සිසුවෙකුට 'පෙරදිග ආසියාතික කලාව' ඉගෙනීමෙන් ලැබෙන ප්‍රධාන සංසන්දනාත්මක අවබෝධය කුමක්ද?", "ශ්‍රී ලාංකේය කලාව හා ආසියානු කලා මූලයන් හඳුනා ගැනීම", "යුරෝපීය පරිගණක ග්‍රැෆික් ක්‍රම පුහුණු වීම", "කෘත්‍රිම ප්ලාස්ටික් භාණ්ඩ වෙළඳපොළ අධ්‍යයනය", "ගණිතමය ත්‍රිකෝණමිතික සමීකරණ විසඳීම", "ඉන්දීය මූර්ති-සිතුවම් ආභාසය හා චීන-ජපන් පින්සල්-මුද්‍රණ තාක්ෂණය දේශීය කලාව වටහා ගැනීමට උදව් වේ.")
    )
}
